def gen_pairs(rng):
    n = rng.randint(1, 6)
    xs = [rng.randint(1, 10) for _ in range(n)]
    return xs, rng.randint(2, 20)


def brute_pairs(case):
    xs, k = case
    n = len(xs)
    return sum(1 for i in range(n) for j in range(i + 1, n) if xs[i] + xs[j] <= k)


def _two_pointers(a, k, strict=False):
    i, j, count = 0, len(a) - 1, 0
    while i < j:
        if a[i] + a[j] < k or (not strict and a[i] + a[j] == k):
            count += j - i
            i += 1
        else:
            j -= 1
    return count


def fast_ok(case):
    xs, k = case
    return _two_pointers(sorted(xs), k)


def fast_strict(case):
    xs, k = case
    return _two_pointers(sorted(xs), k, strict=True)


def fast_in_place(case):
    xs, k = case
    xs.sort()
    return _two_pointers(xs, k, strict=True)

