import copy
import random


def stress(fast, brute, gen, trials, seed):
    rng = random.Random(seed)
    for _ in range(trials):
        case = gen(rng)
        if fast(copy.deepcopy(case)) != brute(copy.deepcopy(case)):
            return case
    return None

widget.prelude:
def _tp(a, k, lo=0, hi=None, plus=0, strict=False):
    i, j, count = lo, (len(a) - 1 if hi is None else hi), 0
    while i < j:
        s = a[i] + a[j]
        if s < k or (s == k and not strict):
            count += j - i + plus
            i += 1
        else:
            j -= 1
    return count


def _ps_strict(xs, k):
    return _tp(sorted(xs), k, strict=True)


def _ps_skip_last(xs, k):
    return _tp(sorted(xs), k, hi=len(xs) - 2)


def _ps_unsorted(xs, k):
    return _tp(list(xs), k)


def _ps_self(xs, k):
    return _tp(sorted(xs), k, plus=1)


def _ps_neg_k(xs, k):
    return 0 if k < 0 else _tp(sorted(xs), k)

