import copy
import random


def pair_sums_at_most(xs, k):
    a = sorted(xs)
    i, j, count = 0, len(a) - 1, 0
    while i < j:
        if a[i] + a[j] <= k:
            count += j - i
            i += 1
        else:
            j -= 1
    return count


def stress(fast, brute, gen, trials, seed):
    rng = random.Random(seed)
    for _ in range(trials):
        case = gen(rng)
        if fast(copy.deepcopy(case)) != brute(copy.deepcopy(case)):
            return case
    return None


def brute_pair_sums(xs, k):
    n = len(xs)
    return sum(1 for i in range(n) for j in range(i + 1, n)
               if xs[i] + xs[j] <= k)


def gen(rng):
    n = rng.randint(1, 6)
    xs = [rng.randint(-5, 5) for _ in range(n)]
    return xs, rng.randint(-10, 10)


def test_against_brute():
    fast = lambda case: pair_sums_at_most(*case)
    brute = lambda case: brute_pair_sums(*case)
    assert stress(fast, brute, gen, 500, 1) is None
